create table public.hidden_messages(user_id uuid not null references public.profiles(id) on delete cascade,message_id uuid not null references public.messages(id) on delete cascade,created_at timestamptz not null default now(),primary key(user_id,message_id));
create table public.starred_messages(user_id uuid not null references public.profiles(id) on delete cascade,message_id uuid not null references public.messages(id) on delete cascade,created_at timestamptz not null default now(),primary key(user_id,message_id));
create table public.message_reactions(message_id uuid not null references public.messages(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,reaction text not null check(reaction in ('❤️','👍','😂','🔥','😮')),created_at timestamptz not null default now(),primary key(message_id,user_id,reaction));
create table public.pinned_messages(conversation_id uuid primary key references public.conversations(id) on delete cascade,message_id uuid not null references public.messages(id) on delete cascade,pinned_by uuid not null references public.profiles(id),created_at timestamptz not null default now());
create index hidden_message_id on public.hidden_messages(message_id);
create index starred_message_id on public.starred_messages(message_id);
create index reactions_user on public.message_reactions(user_id);
create index pin_message on public.pinned_messages(message_id);
create index pin_user on public.pinned_messages(pinned_by);
alter table public.hidden_messages enable row level security;
alter table public.starred_messages enable row level security;
alter table public.message_reactions enable row level security;
alter table public.pinned_messages enable row level security;
create policy hidden_read on public.hidden_messages for select to authenticated using(user_id=auth.uid() and nanba_private.message_access(message_id));
create policy hidden_insert on public.hidden_messages for insert to authenticated with check(user_id=auth.uid() and nanba_private.message_access(message_id));
create policy hidden_delete on public.hidden_messages for delete to authenticated using(user_id=auth.uid() and nanba_private.message_access(message_id));
create policy starred_read on public.starred_messages for select to authenticated using(user_id=auth.uid() and nanba_private.message_access(message_id));
create policy starred_insert on public.starred_messages for insert to authenticated with check(user_id=auth.uid() and nanba_private.message_access(message_id));
create policy starred_delete on public.starred_messages for delete to authenticated using(user_id=auth.uid() and nanba_private.message_access(message_id));
create policy reaction_read on public.message_reactions for select to authenticated using(nanba_private.message_access(message_id));
create policy reaction_insert on public.message_reactions for insert to authenticated with check(user_id=auth.uid() and nanba_private.message_access(message_id));
create policy reaction_delete on public.message_reactions for delete to authenticated using(user_id=auth.uid() and nanba_private.message_access(message_id));
create policy pin_read on public.pinned_messages for select to authenticated using(nanba_private.member(conversation_id));
create policy pin_insert on public.pinned_messages for insert to authenticated with check(pinned_by=auth.uid() and exists(select 1 from public.messages m where m.id=message_id and m.conversation_id=pinned_messages.conversation_id and m.deleted_for_everyone_at is null) and nanba_private.member(conversation_id));
create policy pin_update on public.pinned_messages for update to authenticated using(nanba_private.member(conversation_id)) with check(pinned_by=auth.uid() and exists(select 1 from public.messages m where m.id=message_id and m.conversation_id=pinned_messages.conversation_id and m.deleted_for_everyone_at is null) and nanba_private.member(conversation_id));
create policy pin_delete on public.pinned_messages for delete to authenticated using(nanba_private.member(conversation_id));
revoke all on public.hidden_messages,public.starred_messages,public.message_reactions,public.pinned_messages from anon,authenticated;
grant select,insert,delete on public.hidden_messages,public.starred_messages,public.message_reactions to authenticated;
grant select,insert,update,delete on public.pinned_messages to authenticated;
alter publication supabase_realtime add table public.message_reactions,public.pinned_messages;
